using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.LoyaltyDiscount;

public sealed class TierDiscountAcceptanceTests
{
    // Member receives the loyalty discount of their tier
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 500, 9_500)]
    [InlineData(LoyaltyTier.Silver, 1_000, 9_000)]
    [InlineData(LoyaltyTier.Gold, 1_500, 8_500)]
    public void MemberReceivesTheLoyaltyDiscountOfTheirTier(LoyaltyTier loyaltyTier, int expectedDiscountCents, int expectedTotalCents)
    {
        var quote = new CalculateLoyaltyDiscount().Handle(new CalculateLoyaltyDiscountQuery(10_000, loyaltyTier));

        Assert.Equal(new LoyaltyDiscountQuote(10_000, expectedDiscountCents, expectedTotalCents, loyaltyTier), quote);
    }
}
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed record CalculateLoyaltyDiscountQuery(int SubtotalCents, LoyaltyTier LoyaltyTier);

public sealed record LoyaltyDiscountQuote(
    int SubtotalCents,
    int DiscountCents,
    int TotalCents,
    LoyaltyTier LoyaltyTier);

public sealed class CalculateLoyaltyDiscount
{
    public LoyaltyDiscountQuote Handle(CalculateLoyaltyDiscountQuery query)
    {
        var discount = query.SubtotalCents * PercentFor(query.LoyaltyTier) / 100;
        return new(query.SubtotalCents, discount, query.SubtotalCents - discount, query.LoyaltyTier);
    }

    private static int PercentFor(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        _ => 0,
    };
}
namespace CheckoutPricing.Domain;

public enum LoyaltyTier
{
    Bronze,
    Silver,
    Gold
}
